-- Registre opérationnel de conformité du cabinet : obligations, preuves et actions correctives.
ALTER TABLE public.conformite_obligations
  ADD COLUMN IF NOT EXISTS code text,
  ADD COLUMN IF NOT EXISTS reference_url text,
  ADD COLUMN IF NOT EXISTS action_requise text,
  ADD COLUMN IF NOT EXISTS preuve_reference text,
  ADD COLUMN IF NOT EXISTS derniere_revue date,
  ADD COLUMN IF NOT EXISTS mis_a_jour_par uuid REFERENCES auth.users(id);

CREATE UNIQUE INDEX IF NOT EXISTS conformite_obligations_code_uidx
  ON public.conformite_obligations(code) WHERE code IS NOT NULL;

CREATE TABLE IF NOT EXISTS public.conformite_actions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  obligation_id uuid REFERENCES public.conformite_obligations(id) ON DELETE SET NULL,
  titre text NOT NULL,
  description text,
  priorite text NOT NULL DEFAULT 'normale' CHECK (priorite IN ('basse','normale','haute','critique')),
  statut text NOT NULL DEFAULT 'a_faire' CHECK (statut IN ('a_faire','en_cours','en_attente','terminee','annulee')),
  responsable text,
  echeance date,
  preuve_reference text,
  resolution text,
  cree_par uuid REFERENCES auth.users(id),
  cloture_le timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.conformite_actions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS conformite_actions_staff_all ON public.conformite_actions;
CREATE POLICY conformite_actions_staff_all ON public.conformite_actions
  FOR ALL TO authenticated
  USING (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'mandataire'))
  WITH CHECK (public.has_role(auth.uid(), 'admin') OR public.has_role(auth.uid(), 'mandataire'));
COMMENT ON TABLE public.conformite_actions IS 'Registre horodaté des actions de mise en conformité et corrections du cabinet.';

INSERT INTO public.conformite_obligations
(code,niveau,domaine,libelle,description,periodicite,preuve_attendue,reference_url,action_requise,statut)
VALUES
('ORIAS-01','cabinet','Accès à la profession','Immatriculation ORIAS valide','Vérifier l’immatriculation du cabinet, les catégories d’activité et les informations publiées.','Annuelle et à chaque changement','Attestation ou fiche ORIAS à jour','https://www.orias.fr/','Télécharger et vérifier l’attestation ORIAS et prévoir le renouvellement annuel.','a_definir'),
('ASSO-01','cabinet','Accès à la profession','Adhésion à une association professionnelle agréée','Vérifier l’adhésion obligatoire du courtier et l’adéquation de l’association à l’activité exercée.','Annuelle','Attestation d’adhésion et preuve de cotisation','https://acpr.banque-france.fr/fr/professionnels/lacpr-vous-accompagne/intermediaires/espace-pour-les-intermediaires','Confirmer l’association, l’échéance et conserver l’attestation.','a_definir'),
('RCP-01','cabinet','Accès à la profession','Responsabilité civile professionnelle','Vérifier la validité, les plafonds, franchises et périmètre de la garantie RCP.','Annuelle et à chaque renouvellement','Attestation RCP et contrat','https://www.orias.fr/','Vérifier l’attestation en cours et sa couverture effective.','a_definir'),
('GF-01','cabinet','Accès à la profession','Garantie financière si applicable','Déterminer si le cabinet encaisse des fonds pour compte de tiers et vérifier si une garantie financière est requise.','Annuelle et à chaque changement de flux','Analyse d’applicabilité et attestation si requise','https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006073984/','Documenter l’applicabilité selon les flux réellement encaissés.','a_definir'),
('HON-01','cabinet','Honorabilité et capacité','Honorabilité des dirigeants et personnes concernées','Vérifier les conditions d’honorabilité des personnes concernées selon les fonctions exercées.','À l’entrée et à chaque changement','Dossier de vérification approprié','https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006073984/','Documenter les vérifications et les responsabilités internes.','a_definir'),
('DDA-01','cabinet','Formation DDA','Formation professionnelle continue de 15 heures','Suivre et justifier au moins 15 heures annuelles pour chaque personne entrant dans le champ de l’obligation, avec thèmes, date, durée et organisme.','Annuelle','Attestations et registre individuel des formations','https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000036979532/','Vérifier les heures de l’année pour chaque personne concernée et programmer les heures manquantes.','a_definir'),
('DER-01','cabinet','Information précontractuelle','Document d’entrée en relation','Vérifier que les informations réglementaires du cabinet, ORIAS, réclamations, médiation et liens avec assureurs sont communiquées avant la relation d’affaires.','À chaque entrée en relation et à chaque mise à jour','Modèle DER en vigueur et exemples datés','https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000036920566/','Contrôler le modèle actuel et un échantillon de dossiers récents.','a_definir'),
('DDA-02','client_dossier','Devoir de conseil','Recueil écrit des exigences et besoins','Le recueil doit être adapté au client et au produit proposé, et conservé dans le dossier.','À chaque souscription et en cas de changement pertinent','Recueil daté et archivé dans le dossier','https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000036920558/','Contrôler un échantillon de dossiers par branche et corriger les lacunes.','a_definir'),
('DDA-03','client_dossier','Devoir de conseil','Justification de la recommandation','Tracer pourquoi le contrat recommandé correspond aux exigences et besoins du client.','À chaque conseil et souscription','Devoir de conseil, comparaison et justification conservés','https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000036920558/','Vérifier la présence d’une justification individualisée dans les dossiers contrôlés.','a_definir'),
('DDA-04','cabinet','Gouvernance produits','Marché cible et gouvernance des produits','Comprendre le marché cible, les caractéristiques du produit, ses risques et les modalités de distribution communiquées par les concepteurs.','À chaque nouveau produit et lors des revues','Documents de gouvernance produits et consignes partenaires','https://acpr.banque-france.fr/fr/publications-et-statistiques/publications/recommandation-2024-r-01-du-28-juin-2024-sur-la-mise-en-oeuvre-de-certaines-dispositions-issues-de','Documenter les produits distribués et la revue des informations partenaires.','a_definir'),
('REM-01','cabinet','Rémunération et conflits d’intérêts','Information sur la nature de la rémunération','Informer le client de la rémunération liée au contrat et communiquer les honoraires ou leur méthode de calcul lorsqu’ils sont dus par le client.','À chaque relation/contrat concerné','DER, documents précontractuels et convention d’honoraires','https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000036920566/','Vérifier les mentions de rémunération et les supports utilisés.','a_definir'),
('REM-02','cabinet','Rémunération et conflits d’intérêts','Prévention des conflits d’intérêts','Identifier et gérer les conflits potentiels, y compris ceux liés aux commissions, objectifs et avantages économiques.','Annuelle et à chaque changement','Procédure et registre des conflits, décisions prises','https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000036920570/','Formaliser la procédure et consigner les conflits identifiés et leur traitement.','a_definir'),
('REC-01','cabinet','Réclamations','Procédure de traitement des réclamations','Identifier les réclamations quel que soit le canal, tracer leur réception, accusé, analyse, réponse, délais et voies de recours.','À chaque réclamation et revue annuelle','Procédure à jour et registre de réclamations','https://acpr.banque-france.fr/fr/publications-et-statistiques/publications/recommandation-2024-r-02-du-2-juillet-2024-sur-le-traitement-des-reclamations','Vérifier la procédure publiée, le registre et les délais de réponse applicables.','a_definir'),
('MED-01','cabinet','Réclamations','Information sur la médiation','Vérifier que les coordonnées et modalités de saisine du médiateur compétent sont accessibles et remises aux clients selon les exigences applicables.','Annuelle et à chaque changement','DER, site, supports client et convention de médiation','https://acpr.banque-france.fr/fr/publications-et-statistiques/publications/recommandation-2024-r-02-du-2-juillet-2024-sur-le-traitement-des-reclamations','Vérifier le médiateur compétent et les informations publiées sur les supports clients.','a_definir'),
('LCB-01','cabinet','LCB-FT','Classification des risques LCB-FT','Établir une classification des risques documentée tenant compte des clients, produits, opérations, canaux et zones géographiques pertinents.','Annuelle et lors d’un changement majeur','Cartographie LCB-FT validée et datée','https://acpr.banque-france.fr/fr/reglementation/focus-sur-la-reglementation/reglementation-en-matiere-de-lcb-ft','Réviser et valider la cartographie des risques LCB-FT du cabinet.','a_definir'),
('LCB-02','client_dossier','LCB-FT','Identification et connaissance du client','Mettre en œuvre les mesures d’identification, vérification et connaissance du client selon les risques et l’activité.','À l’entrée en relation et selon le risque','Pièces KYC, données de connaissance et traces de vérification','https://acpr.banque-france.fr/fr/reglementation/focus-sur-la-reglementation/reglementation-en-matiere-de-lcb-ft','Contrôler les dossiers et les règles de vigilance selon le profil de risque.','a_definir'),
('LCB-03','cabinet','LCB-FT','PPE, sanctions et gel des avoirs','Prévoir le filtrage et le traitement des personnes politiquement exposées, sanctions et mesures de gel applicables, avec traçabilité des décisions.','À l’entrée en relation et en continu selon le dispositif','Procédure, résultats de filtrage et décisions tracées','https://acpr.banque-france.fr/fr/reglementation/focus-sur-la-reglementation/reglementation-en-matiere-de-lcb-ft','Vérifier la procédure, les contrôles réalisés et les modalités d’escalade.','a_definir'),
('LCB-04','cabinet','LCB-FT','Déclaration de soupçon et échanges avec Tracfin','Définir les critères d’escalade, la confidentialité et le processus de déclaration lorsque requis.','Continue','Procédure LCB-FT et traces conservées dans un espace à accès restreint','https://acpr.banque-france.fr/fr/reglementation/focus-sur-la-reglementation/reglementation-en-matiere-de-lcb-ft','Vérifier l’existence d’une procédure et la sensibilisation des personnes concernées.','a_definir'),
('LCB-05','cabinet','LCB-FT','Formation LCB-FT','Former les personnes concernées et conserver les preuves des formations et mises à jour.','À l’entrée et périodiquement','Attestations, programme et présence','https://acpr.banque-france.fr/fr/reglementation/focus-sur-la-reglementation/reglementation-en-matiere-de-lcb-ft','Identifier les personnes à former et planifier les renouvellements requis.','a_definir'),
('RGPD-01','cabinet','Protection des données','Registre des traitements RGPD','Tenir une documentation des traitements, finalités, bases légales, catégories de données, destinataires, durées de conservation et mesures de sécurité.','À chaque nouveau traitement et revue annuelle','Registre des traitements à jour','https://www.cnil.fr/fr/documenter-la-conformite','Vérifier l’exhaustivité et la mise à jour du registre des traitements.','a_definir'),
('RGPD-02','cabinet','Protection des données','Information et droits des personnes','Publier les mentions d’information et organiser le traitement des demandes d’accès, rectification, opposition, effacement et autres droits applicables.','Continue','Mentions, procédure et registre des demandes','https://www.cnil.fr/fr/ma-conformite-au-rgpd/me-mettre-en-conformite','Vérifier les mentions d’information et le registre des demandes reçues.','a_definir'),
('RGPD-03','cabinet','Protection des données','Violations de données personnelles','Détecter, qualifier, documenter et notifier les violations à l’autorité et aux personnes concernées lorsque les critères réglementaires sont réunis.','À chaque incident','Registre des violations et procédure d’incident','https://www.cnil.fr/fr/violation-de-donnees-personnelles','Vérifier la procédure de violation et les contacts d’escalade.','a_definir'),
('RGPD-04','cabinet','Protection des données','Contrats de sous-traitance et sécurité','Vérifier les clauses RGPD, les habilitations, la sécurité et les transferts éventuels avec les prestataires.','À chaque nouveau prestataire et revue annuelle','Contrats, clauses de sous-traitance et revue des accès','https://www.cnil.fr/fr/les-obligations-des-sous-traitants','Lister les prestataires qui traitent des données et contrôler leurs garanties contractuelles.','a_definir'),
('DORA-01','cabinet','Résilience numérique','Applicabilité DORA et gestion des incidents TIC','Documenter l’applicabilité selon la taille et le statut du courtier. Pour les entités concernées, organiser le registre d’informations, la gestion des risques TIC et la notification des incidents selon le régime applicable.','Annuelle et à chaque changement de taille/statut','Analyse d’applicabilité signée et, si applicable, documents DORA','https://acpr.banque-france.fr/fr/reglementation/focus-sur-la-reglementation/transverse/digital-operational-resilience-act-dora/faq-sur-la-directive-et-le-reglement-dora','Confirmer l’effectif et les seuils de l’activité d’intermédiation, puis documenter la conclusion d’applicabilité.','a_definir'),
('CTRL-01','cabinet','Contrôle interne','Plan de contrôle et suivi des anomalies','Définir des contrôles périodiques proportionnés aux risques, consigner les résultats et suivre les mesures correctives jusqu’à leur clôture.','Trimestrielle et revue annuelle','Plan de contrôle, échantillons, résultats et actions correctives','https://acpr.banque-france.fr/fr/professionnels/lacpr-vous-accompagne/intermediaires/espace-pour-les-intermediaires','Valider le plan de contrôle et documenter chaque anomalie jusqu’à résolution.','a_definir'),
('VEILLE-01','cabinet','Veille réglementaire','Veille et analyse d’impact réglementaire','Surveiller les évolutions applicables, décider de leur impact sur les produits, procédures et dossiers, et garder la preuve de l’analyse.','Mensuelle et à chaque publication pertinente','Journal de veille, analyse d’impact et décisions','https://acpr.banque-france.fr/fr/reglementation/focus-sur-la-reglementation/reglementation-en-matiere-de-protection-de-la-clientele','Vérifier que les nouveautés pertinentes génèrent une analyse, une décision et si nécessaire une action.','a_definir'),
('ARCH-01','cabinet','Traçabilité et conservation','Archivage des dossiers et preuves','Définir des durées de conservation par catégorie de document, garantir la disponibilité, l’intégrité et l’accès restreint aux preuves.','Annuelle et lors d’un changement de procédure','Politique de conservation et dossiers archivés','https://www.cnil.fr/fr/ma-conformite-au-rgpd/me-mettre-en-conformite','Établir une matrice de conservation par type de document et vérifier les accès.','a_definir'),
('ACPR-01','cabinet','Relations avec le superviseur','Contribution annuelle pour frais de contrôle','Vérifier l’obligation applicable au cabinet et conserver l’avis et la preuve de paiement de la contribution ACPR.','Annuelle','Avis et justificatif de paiement','https://acpr.banque-france.fr/en/node/32869','Vérifier l’échéance et conserver le justificatif annuel.','a_definir')
